sys_script_client.script:
function onSubmit() {

    g_form.clearMessages();

    var numberFields = {
        net: 'Net',
        gross: 'Gross',
        lop_days: 'LOP Days',
        working_days: 'Working Days',
        manual_adjustment_amount: 'Manual Adjustment Amount'
    };
    var firstInvalidField = '';

    for (var field in numberFields) {
        var value = g_form.getValue(field);

        if (value !== '' && parseFloat(value.replace(/[^0-9.\-]/g, '')) < 0) {
            g_form.addErrorMessage(numberFields[field] + ' cannot be negative.');
            firstInvalidField = firstInvalidField || field;
        }
    }

    var lopDays = g_form.getValue('lop_days');
    var workingDays = g_form.getValue('working_days');

    if (lopDays !== '' && workingDays !== '' && parseFloat(lopDays) > parseFloat(workingDays)) {
        g_form.addErrorMessage('LOP Days cannot exceed Working Days.');
        firstInvalidField = firstInvalidField || 'lop_days';
    }

    if (firstInvalidField) {
        g_form.getControl(firstInvalidField).focus();
        return false;
    }
}
